const searchUsersForShare = `-- name: SearchUsersForShare :many
SELECT user_id, display_name, username, premium, created_at, updated_at, role, disabled_at, storage_quota_bytes, email, password_hash
FROM /* TEMPLATE: schema */users
WHERE user_id <> $1
  AND disabled_at IS NULL
  AND (
    display_name ILIKE '%' || $2::text || '%'
    OR email ILIKE '%' || $2::text || '%'
    OR username ILIKE '%' || $2::text || '%'
    OR user_id::text = $2::text
  )
ORDER BY email ASC NULLS LAST, username ASC NULLS LAST, display_name ASC NULLS LAST, user_id ASC
LIMIT $3
`

type SearchUsersForShareParams struct {
	ExcludeUserID int64  `json:"exclude_user_id"`
	Search        string `json:"search"`
	PageSize      int32  `json:"page_size"`
}

func (q *Queries) SearchUsersForShare(ctx context.Context, arg SearchUsersForShareParams) ([]*User, error) {
	rows, err := q.db.Query(ctx, searchUsersForShare, arg.ExcludeUserID, arg.Search, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*User{}
	for rows.Next() {
		var i User
		if err := rows.Scan(
			&i.UserID,
			&i.DisplayName,
			&i.Username,
			&i.Premium,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Role,
			&i.DisabledAt,
			&i.StorageQuotaBytes,
			&i.Email,
			&i.PasswordHash,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

